class Solution {
    private fun count(grid:Array<IntArray>):Int{
        val rows=grid.size;
        val cols=grid[0].size;
        val height=Array(rows){
            IntArray(cols)
        };
        var answer=0;
        for(row in rows-1 downTo 0)for(col in 0 until cols)if(grid[row][col]==1){
            height[row][col]=1;
            if(row+1<rows&&col>0&&col+1<cols)height[row][col]+=minOf(height[row+1][col-1],height[row+1][col],height[row+1][col+1]);
            answer+=height[row][col]-1
        };
        return answer
    };
    fun countPyramids(grid:Array<IntArray>):Int{
        val answer=count(grid);
        grid.reverse();
        return answer+count(grid)
    }
}

